package com.dy.artisan3d.ui.componentimport android.content.Contextimport androidx.compose.animation.AnimatedVisibilityimport androidx.compose.animation.core.*import androidx.compose.animation.fadeInimport androidx.compose.animation.fadeOutimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.gestures.detectTransformGesturesimport androidx.compose.foundation.isSystemInDarkThemeimport androidx.compose.foundation.layout.*import androidx.compose.foundation.shape.CircleShapeimport androidx.compose.foundation.shape.RoundedCornerShapeimport androidx.compose.material.icons.Iconsimport androidx.compose.material.icons.filled.Refreshimport androidx.compose.material.icons.filled.Warningimport androidx.compose.material3.*import androidx.compose.runtime.*import androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.graphics.Brushimport androidx.compose.ui.graphics.Colorimport androidx.compose.ui.graphics.StrokeCapimport androidx.compose.ui.input.pointer.pointerInputimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.platform.LocalLifecycleOwnerimport androidx.compose.ui.text.font.FontWeightimport androidx.compose.ui.text.style.TextAlignimport androidx.compose.ui.unit.dpimport androidx.compose.ui.unit.spimport androidx.lifecycle.Lifecycleimport androidx.lifecycle.LifecycleEventObserverimport io.github.sceneview.Sceneimport io.github.sceneview.node.CameraNodeimport io.github.sceneview.node.ModelNodeimport io.github.sceneview.rememberEngineimport io.github.sceneview.rememberModelLoaderimport io.github.sceneview.rememberNodeimport io.github.sceneview.rememberNodesimport io.github.sceneview.math.Positionimport io.github.sceneview.math.Rotationimport io.github.sceneview.math.Scaleimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.withContextimport org.jetbrains.compose.resources.stringResourceimport java.io.Fileimport java.net.HttpURLConnectionimport java.net.URLimport java.nio.ByteBufferimport org.jetbrains.compose.resources.stringResourceimport artisan3d.composeapp.generated.resources.* // Res klassi uchun// ─── State ────────────────────────────────────────────────────────────────────private sealed class LoadState {    object Idle : LoadState()    data class Downloading(val progress: Float, val downloadedMb: Float, val totalMb: Float) : LoadState()    object Processing : LoadState()    object Success : LoadState()    data class Error(val message: String) : LoadState()}// ─── Composable ───────────────────────────────────────────────────────────────@Composableactual fun ModelViewer(    modelUrl: String,    siteUrl: String,    modifier: Modifier,    autoRotate: Boolean,    enableZoom: Boolean,    enablePan: Boolean,    onLoaded: () -> Unit,    onError: (String) -> Unit) {    val context   = LocalContext.current    val lifecycle = LocalLifecycleOwner.current.lifecycle    // ✅ Dark/Light mode aniqlash    val isDarkMode = isSystemInDarkTheme()    val backgroundColor = if (isDarkMode) Color.Black else Color.White    val engine      = rememberEngine()    val modelLoader = rememberModelLoader(engine)    val childNodes  = rememberNodes()    var loadState    by remember { mutableStateOf<LoadState>(LoadState.Idle) }    var retryKey     by remember { mutableStateOf(0) }    // ✅ Yaxshilangan gesture state    var targetRotX   by remember { mutableFloatStateOf(40f) }    var targetRotY   by remember { mutableFloatStateOf(4f) }    var targetScale  by remember { mutableFloatStateOf(0.8f) }    var currentRotX  by remember { mutableFloatStateOf(40f) }    var currentRotY  by remember { mutableFloatStateOf(4f) }    var currentScale by remember { mutableFloatStateOf(0.8f) }    var velocityX    by remember { mutableFloatStateOf(0f) }    var velocityY    by remember { mutableFloatStateOf(0f) }    var isDragging   by remember { mutableStateOf(false) }    val cameraNode = rememberNode {        CameraNode(engine = engine).apply {            position = Position(x = 0f, y = 0f, z = 5f)            lookAt(Position(0f, 0f, 0f))        }    }    val modelLoadError = stringResource(Res.string.model_load_error)    val modelOpenError = stringResource(Res.string.model_open_error)    val urlInvalid = stringResource(Res.string.error_url_invalid)    val urlServer = stringResource(Res.string.error_server_code)    val urlFileEmpty = stringResource(Res.string.error_file_empty)    val unknown = stringResource(Res.string.error_unknown)    var isActive by remember { mutableStateOf(true) }    DisposableEffect(lifecycle) {        val observer = LifecycleEventObserver { _, event ->            isActive = event != Lifecycle.Event.ON_STOP        }        lifecycle.addObserver(observer)        onDispose { lifecycle.removeObserver(observer) }    }    LaunchedEffect(modelUrl, retryKey) {        loadState = LoadState.Idle        childNodes.clear()        try {            val cachedFile = withContext(Dispatchers.IO) {                downloadWithProgress(modelUrl,                    urlInvalid, urlServer, urlFileEmpty, unknown,context.cacheDir,) { p, dl, total ->                    loadState = LoadState.Downloading(p, dl, total)                }            }            loadState = LoadState.Processing            val buffer = withContext(Dispatchers.IO) {                ByteBuffer.wrap(cachedFile.readBytes())            }            val modelInstance = modelLoader.createModelInstance(buffer)            val modelNode = ModelNode(                modelInstance = modelInstance,                scaleToUnits  = null,                centerOrigin  = Position(0f, 0f, 0f)            ).apply {                scale              = Scale(currentScale)                position           = Position(0f, 0f, 0f)                rotation           = Rotation(currentRotX, currentRotY, 0f)                isEditable         = false                isPositionEditable = false                isRotationEditable = false                isScaleEditable    = false            }            childNodes.add(modelNode)            loadState = LoadState.Success            onLoaded()        } catch (e: DownloadException) {            val msg = modelLoadError+": ${e.message}"            loadState = LoadState.Error(msg); onError(msg)        } catch (e: Exception) {            val msg = modelOpenError+": ${e.message}"            loadState = LoadState.Error(msg); onError(msg)        }    }    Box(        modifier = modifier.background(backgroundColor) // ✅ Background color    ) {        AnimatedVisibility(            visible = loadState is LoadState.Success,            enter   = fadeIn(tween(600)),            exit    = fadeOut()        ) {            if (isActive) {                Scene(                    modifier = Modifier                        .fillMaxSize()                        .pointerInput(enableZoom, enablePan) {                            detectTransformGestures { _, pan, zoom, _ ->                                isDragging = true                                // ✅ Yaxshilangan sensitivity va to'g'ri yo'nalish                                val sensitivity = 0.25f // Pastroq = silliqroq                                // ✅ X o'qi: barmoq harakati yo'nalishida (chapga -> chap, o'ngga -> o'ng)                                targetRotY += pan.x * sensitivity                                velocityY = pan.x * sensitivity * 0.8f                                // ✅ Y o'qi: yuqoriga -> yuqori, pastga -> pastga (teskari emas!)                                targetRotX += pan.y * sensitivity                                targetRotX = targetRotX.coerceIn(-85f, 85f)                                velocityX = pan.y * sensitivity * 0.8f                                if (enableZoom) {                                    targetScale = (targetScale * zoom).coerceIn(0.1f, 2.5f)                                }                            }                        },                    engine      = engine,                    modelLoader = modelLoader,                    cameraNode  = cameraNode,                    childNodes  = childNodes,                    onFrame     = { _ ->                        val model = childNodes.firstOrNull() as? ModelNode ?: return@Scene                        val lerpFactor = 0.15f // ✅ Biroz yumshoqroq interpolatsiya                        if (!isDragging) {                            if (autoRotate) targetRotY += 0.3f                            // ✅ Ikki o'q bo'yicha inertia                            velocityY *= 0.94f                            velocityX *= 0.94f                            targetRotY += velocityY                            targetRotX += velocityX                            targetRotX = targetRotX.coerceIn(-85f, 85f)                            if (kotlin.math.abs(velocityY) < 0.01f) velocityY = 0f                            if (kotlin.math.abs(velocityX) < 0.01f) velocityX = 0f                        }                        isDragging = false                        currentRotX  = lerp(currentRotX,  targetRotX,  lerpFactor)                        currentRotY  = lerp(currentRotY,  targetRotY,  lerpFactor)                        currentScale = lerp(currentScale, targetScale, lerpFactor)                        model.rotation = Rotation(currentRotX, currentRotY, 0f)                        model.scale    = Scale(currentScale)                    }                )            }        }        when (val s = loadState) {            is LoadState.Idle        -> LoadingOverlay(0f, stringResource(Res.string.model_preparing))            is LoadState.Processing  -> LoadingOverlay(1f, stringResource(Res.string.model_processing))            is LoadState.Downloading -> LoadingOverlay(s.progress,stringResource(Res.string.model_loading), s.downloadedMb, s.totalMb)            is LoadState.Error       -> ErrorOverlay(                message      = s.message,                onRetry      = { retryKey++ },                onRetryFresh = { clearCache(context, modelUrl); retryKey++ }            )            is LoadState.Success -> {}        }    }}private fun lerp(from: Float, to: Float, fraction: Float) = from + (to - from) * fractionprivate fun clearCache(context: Context, url: String) {    val name = url.substringAfterLast("/").substringBefore("?").ifBlank { "model.glb" }    File(context.cacheDir, name).delete()    File(context.cacheDir, "$name.tmp").delete()}// ─── Loading UI ───────────────────────────────────────────────────────────────@Composableprivate fun LoadingOverlay(    progress: Float,    label: String,    downloadedMb: Float = 0f,    totalMb: Float = 0f) {    val anim by animateFloatAsState(progress, tween(300), label = "p")    val inf  = rememberInfiniteTransition(label = "inf")    val glow by inf.animateFloat(0.2f, 0.6f, infiniteRepeatable(tween(900), RepeatMode.Reverse), label = "g")    Box(Modifier.fillMaxSize().background(Color(0xF0101418)), Alignment.Center) {        Column(horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(20.dp)) {            Box(                Modifier.size(88.dp).clip(CircleShape)                    .background(Brush.radialGradient(listOf(Color(0xFF00E5FF).copy(alpha = glow * 0.3f), Color.Transparent))),                Alignment.Center            ) {                CircularProgressIndicator(                    progress    = { anim },                    modifier    = Modifier.size(60.dp),                    color       = Color(0xFF00E5FF),                    trackColor  = Color(0xFF1E2A35),                    strokeWidth = 4.dp,                    strokeCap   = StrokeCap.Round                )                if (progress in 0.01f..0.99f) {                    Text("${(progress * 100).toInt()}%", color = Color(0xFF00E5FF), fontSize = 12.sp, fontWeight = FontWeight.Bold)                }            }            Text(label, color = Color(0xCCFFFFFF), fontSize = 15.sp, fontWeight = FontWeight.Medium)            if (totalMb > 0f) {                Text("${"%.1f".format(downloadedMb)} / ${"%.1f".format(totalMb)} MB", color = Color(0x8800E5FF), fontSize = 12.sp)                Box(Modifier.width(200.dp).height(3.dp).clip(RoundedCornerShape(2.dp)).background(Color(0xFF1E2A35))) {                    Box(Modifier.fillMaxHeight().fillMaxWidth(anim).clip(RoundedCornerShape(2.dp))                        .background(Brush.horizontalGradient(listOf(Color(0xFF00B4D8), Color(0xFF00E5FF)))))                }            }        }    }}// ─── Error UI ─────────────────────────────────────────────────────────────────@Composableprivate fun ErrorOverlay(message: String, onRetry: () -> Unit, onRetryFresh: () -> Unit) {    Box(Modifier.fillMaxSize().background(Color(0xF0101418)), Alignment.Center) {        Column(            horizontalAlignment = Alignment.CenterHorizontally,            verticalArrangement = Arrangement.spacedBy(16.dp),            modifier = Modifier.padding(horizontal = 32.dp)        ) {            Box(Modifier.size(72.dp).clip(CircleShape).background(Color(0x22FF4444)), Alignment.Center) {                Icon(Icons.Default.Warning, null, tint = Color(0xFFFF6B6B), modifier = Modifier.size(36.dp))            }            Text(stringResource(Res.string.model_load_error), color = Color.White, fontSize = 17.sp, fontWeight = FontWeight.SemiBold)            Text(message, color = Color(0x99FFFFFF), fontSize = 12.sp, textAlign = TextAlign.Center, lineHeight = 17.sp)            Spacer(Modifier.height(4.dp))            Button(                onClick  = onRetry,                colors   = ButtonDefaults.buttonColors(containerColor = Color(0xFF00B4D8)),                shape    = RoundedCornerShape(12.dp),                modifier = Modifier.fillMaxWidth()            ) {                Icon(Icons.Default.Refresh, null, modifier = Modifier.size(18.dp))                Spacer(Modifier.width(8.dp))                Text(stringResource(Res.string.retry), fontWeight = FontWeight.Medium)            }            OutlinedButton(                onClick  = onRetryFresh,                border   = androidx.compose.foundation.BorderStroke(1.dp, Color(0x44FF6B6B)),                shape    = RoundedCornerShape(12.dp),                modifier = Modifier.fillMaxWidth()            ) {                Text(stringResource(Res.string.model_retry_fresh), color = Color(0xFFFF6B6B), fontSize = 13.sp)            }        }    }}// ─── Download ─────────────────────────────────────────────────────────────────class DownloadException(message: String) : Exception(message)private suspend fun downloadWithProgress(    urlString: String,    urlInvalid: String,    urlServer: String,    urlFileEmpty: String,    unknown: String,    cacheDir: File,    onProgress: suspend (Float, Float, Float) -> Unit): File = withContext(Dispatchers.IO) {    val fileName  = urlString.substringAfterLast("/").substringBefore("?").ifBlank { "model.glb" }    val localFile = File(cacheDir, fileName)    if (localFile.exists() && localFile.length() > 0L) {        val mb = localFile.length() / 1_048_576f        withContext(Dispatchers.Main) { onProgress(1f, mb, mb) }        return@withContext localFile    }    val conn = (URL(urlString).openConnection() as? HttpURLConnection)        ?: throw DownloadException(urlInvalid)    conn.apply { connectTimeout = 15_000; readTimeout = 60_000; requestMethod = "GET"; connect() }    val code = conn.responseCode    if (code !in 200..299) { conn.disconnect(); throw DownloadException("$urlServer $code") }    val total   = conn.contentLengthLong    var dl      = 0L    val buf     = ByteArray(8 * 1024)    val tmpFile = File(cacheDir, "$fileName.tmp")    try {        conn.inputStream.use { input ->            tmpFile.outputStream().use { out ->                var n: Int                while (input.read(buf).also { n = it } != -1) {                    out.write(buf, 0, n); dl += n                    val p = if (total > 0) (dl.toFloat() / total).coerceIn(0f, 1f) else 0f                    withContext(Dispatchers.Main) {                        onProgress(p, dl / 1_048_576f, if (total > 0) total / 1_048_576f else 0f)                    }                }            }        }        if (tmpFile.length() == 0L) throw DownloadException(urlFileEmpty)        tmpFile.renameTo(localFile)        localFile    } catch (e: Exception) {        tmpFile.delete()        throw if (e is DownloadException) e else DownloadException(e.message ?: unknown)    } finally {        conn.disconnect()    }}// ─── Platform ─────────────────────────────────────────────────────────────────actual fun isModelViewerSupported(): Boolean = trueactual fun getSupportedModelFormats(): List<String> = listOf("glb", "gltf")